SELECT mc.match_candidate_id, mc.bank_transaction_id, mc.target_type, mc.target_id, CASE WHEN mc.target_type = 'SETTLEMENT' THEN participant.settlement_id WHEN mc.target_type = 'LOAN' THEN schedule.contract_id END AS aggregate_id, COALESCE(settlement.title, contract.contract_alias) AS target_name, COALESCE(settlement_user.name, debtor.name) AS participant_name,
AS expected_remaining_amount,
AS amount_match_type, mc.created_at FROM bank_transaction_match_candidate mc JOIN bank_transaction bt ON bt.bank_transaction_id = mc.bank_transaction_id LEFT JOIN payment_obligation obligation ON mc.target_type = 'SETTLEMENT' AND obligation.payment_obligation_id = mc.target_id LEFT JOIN settlement_participant participant ON participant.participant_id = obligation.participant_id LEFT JOIN settlement settlement ON settlement.settlement_id = participant.settlement_id LEFT JOIN users settlement_user ON settlement_user.user_id = participant.user_id LEFT JOIN repayment_schedule schedule ON mc.target_type = 'LOAN' AND schedule.schedule_id = mc.target_id LEFT JOIN loan_contract contract ON contract.contract_id = schedule.contract_id LEFT JOIN users debtor ON debtor.user_id = contract.debtor_id WHERE mc.bank_transaction_id = #{bankTransactionId} AND mc.candidate_status = 'AVAILABLE' AND ( ( mc.target_type = 'SETTLEMENT' AND obligation.obligation_status = 'ACTIVE' AND settlement.settlement_status = 'IN_PROGRESS' AND obligation.expected_amount > COALESCE(( SELECT SUM(pr.amount) FROM payment_record pr WHERE pr.payment_target_type = 'SETTLEMENT' AND pr.target_id = obligation.payment_obligation_id AND pr.record_status = 'CONFIRMED' ), 0) ) OR ( mc.target_type = 'LOAN' AND schedule.status = 'PENDING' AND schedule.total_payment_due > COALESCE(( SELECT SUM(pr.amount) FROM payment_record pr WHERE pr.payment_target_type = 'LOAN' AND pr.target_id = schedule.schedule_id AND pr.record_status = 'CONFIRMED' ), 0) ) ) AND bt.amount >= (
) * 0.10 AND bt.amount <= (
) * 1.10 ORDER BY mc.match_candidate_id ASC

SELECT mc.match_candidate_id, mc.bank_transaction_id, mc.target_type, mc.target_id, CASE WHEN mc.target_type = 'SETTLEMENT' THEN participant.settlement_id WHEN mc.target_type = 'LOAN' THEN schedule.contract_id END AS aggregate_id, COALESCE(settlement.title, contract.contract_alias) AS target_name, COALESCE(settlement_user.name, debtor.name) AS participant_name,
AS expected_remaining_amount,
AS amount_match_type, mc.created_at FROM bank_transaction_match_candidate mc JOIN bank_transaction bt ON bt.bank_transaction_id = mc.bank_transaction_id LEFT JOIN payment_obligation obligation ON mc.target_type = 'SETTLEMENT' AND obligation.payment_obligation_id = mc.target_id LEFT JOIN settlement_participant participant ON participant.participant_id = obligation.participant_id LEFT JOIN settlement settlement ON settlement.settlement_id = participant.settlement_id LEFT JOIN users settlement_user ON settlement_user.user_id = participant.user_id LEFT JOIN repayment_schedule schedule ON mc.target_type = 'LOAN' AND schedule.schedule_id = mc.target_id LEFT JOIN loan_contract contract ON contract.contract_id = schedule.contract_id LEFT JOIN users debtor ON debtor.user_id = contract.debtor_id WHERE mc.bank_transaction_id IN
#{bankTransactionId}
AND mc.candidate_status = 'AVAILABLE' AND ( ( mc.target_type = 'SETTLEMENT' AND obligation.obligation_status = 'ACTIVE' AND settlement.settlement_status = 'IN_PROGRESS' AND obligation.expected_amount > COALESCE(( SELECT SUM(pr.amount) FROM payment_record pr WHERE pr.payment_target_type = 'SETTLEMENT' AND pr.target_id = obligation.payment_obligation_id AND pr.record_status = 'CONFIRMED' ), 0) ) OR ( mc.target_type = 'LOAN' AND schedule.status = 'PENDING' AND schedule.total_payment_due > COALESCE(( SELECT SUM(pr.amount) FROM payment_record pr WHERE pr.payment_target_type = 'LOAN' AND pr.target_id = schedule.schedule_id AND pr.record_status = 'CONFIRMED' ), 0) ) ) AND bt.amount >= (
) * 0.10 AND bt.amount <= (
) * 1.10
AND mc.target_type = #{targetType}
AND CASE WHEN mc.target_type = 'SETTLEMENT' THEN participant.settlement_id WHEN mc.target_type = 'LOAN' THEN schedule.contract_id END = #{aggregateId}
ORDER BY mc.bank_transaction_id ASC, mc.match_candidate_id ASC

